using S3 = Aws.Cdk.Lib.Aws_s3;
using Constructs;
using Org.Cdk8s;
using Cdk8s.Plus;

class MyChartProps
{
    public s3.Bucket Bucket { get; set; }
}

class MyChart : Chart
{
    public MyChart(Construct scope, string id, MyChartProps props) : base(scope, id)
    {

        new Pod(this, "Pod", new Struct {
            Spec = new Struct {
                Containers = new [] {
                    new Container(new Struct {
                        Image = "my-image",
                        Env = new Struct {
                            BUCKET_NAME = EnvValue.FromValue(props.Bucket.BucketName)
                        }
                    }) }
            }
        });
    }
}

