import aws.cdk.lib.aws_s3.*;
import software.constructs.*;
import org.cdk8s.*;
import cdk8s.plus.*;

public class MyChartProps {
    private Object bucket;
    public Object getBucket() {
        return this.bucket;
    }
    public MyChartProps bucket(Object bucket) {
        this.bucket = bucket;
        return this;
    }
}

public class MyChart extends Chart {
    public MyChart(Construct scope, String id, MyChartProps props) {
        super(scope, id);

        Pod.Builder.create(this, "Pod")
                .spec(Map.of(
                        "containers", List.of(
                            Container.Builder.create()
                                    .image("my-image")
                                    .env(Map.of(
                                            "BUCKET_NAME", EnvValue.fromValue(props.getBucket().getBucketName())))
                                    .build())))
                .build();
    }
}

