    public int Replicas { get; set; }
}

class LoadBalancedWebService : Construct
{
    public LoadBalancedWebService(Construct scope, string id, LoadBalancedWebService props) : base(scope, id)
    {

        var deployment = new Deployment(chart, "Deployment", new Struct {
            Spec = new Struct {
                Replicas = props.Replicas,
                PodSpecTemplate = new Struct {
                    Containers = new [] { new Container(new Struct { Image = props.Image }) }
                }
            }
        });

        deployment.Expose(new Struct { Port = props.Port, ServiceType = ServiceType.LOAD_BALANCER });
    }
}

