import constructs "github.com/aws/constructs-go/constructs"
import cdk8s "github.com/cdk8s-team/cdk8s-core-go/cdk8s"
import "github.com/aws-samples/dummy/cdk8splus"

type LoadBalancedWebService struct {
	port *f64
	image *string
	replicas *f64
}

type LoadBalancedWebService struct {
	Construct
}

func NewLoadBalancedWebService(scope Construct, id *string, props LoadBalancedWebService) *LoadBalancedWebService {
	this := &LoadBalancedWebService{}
	constructs.NewConstruct_Override(this, scope, id)

	deployment := kplus.NewDeployment(chart, jsii.String("Deployment"), map[string]map[string]interface{}{
		"spec": map[string]interface{}{
			"replicas": *props.replicas,
			"podSpecTemplate": map[string][]interface{}{
				"containers": []interface{}{
					kplus.NewContainer(map[string]*string{
						"image": *props.image,
					}),
				},
			},
		},
	})

	deployment.expose(map[string]interface{}{
		"port": *props.port,
		"serviceType": kplus.ServiceType_LOAD_BALANCER,
	})
	return this
}

